function mountTicker(el) {
  const rows = [];
  window.addEventListener('resize', () => layout(el, rows));
  setInterval(async () => rows.push(await fetchRow()), 1000);
}

async function saveAll(rows) {
  rows.forEach(async (row) => {
    await save(row);
  });
  console.log('all saved');
}

function SubmissionTable({ rows }) {
  const newest = rows.sort((a, b) => b.createdAt - a.createdAt);
  return <Table rows={newest} />;
}
